#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char *my_strdup(const char *s) {
    size_t n = strlen(s) + 1;          /* 别忘结尾 '\0' */
    char *p = malloc(n);
    if (!p) return NULL;
    memcpy(p, s, n);
    return p;
}

int main(void) {
    const char *src = "hello, dynamic";
    char *copy = my_strdup(src);
    if (!copy) return 1;

    printf("copy = %s\n", copy);
    printf("strlen(copy) = %zu\n", strlen(copy));
    printf("sizeof(copy) = %zu (指针，不是数组)\n", sizeof(copy));

    copy[0] = 'H';                     /* 堆上是可写副本 */
    printf("修改后 = %s (原字面量仍为 %s)\n", copy, src);
    free(copy); copy = NULL;
    return 0;
}
